-- GenDB engine variant Q06-commuted_comparisons: template q06.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  SUM(l_extendedprice * l_discount) AS revenue
FROM lineitem
WHERE
  $1 <= l_shipdate
  AND $1 + INTERVAL '1 YEAR' > l_shipdate
  AND l_discount BETWEEN $2 - 0.01 AND $2 + 0.01
  AND $3 > l_quantity
